product = 1
count = 0
for n in range(1, 9):
    product *= n
for n in range(1, 51):
    if n % 3 == 0 or n % 5 == 0:
        count += 1
print(f"8 factorial: {product}")
print(f"Divisible by 3 or 5: {count}")

example.code:
print("Table:")
for r in range(1, 4):
    for c in range(1, 5):
        print(r * c, end=" ")
    print()
print("Triangle:")
for i in range(4):
    for _ in range(i + 1):
        print("*", end=" ")
    print()

